begin;
create view public.engineering_receivables_aging with(security_invoker=true) as
with paid as(select tenant_id,company_id,installment_id,sum(amount)::numeric(18,2) paid_amount,max(settled_on) last_received_on from public.financial_settlements group by tenant_id,company_id,installment_id)
select l.tenant_id,l.company_id,l.measurement_id,m.competence measurement_competence,c.work_id,w.name work_name,m.contract_id,c.contract_number,l.financial_entry_id,l.financial_installment_id,i.due_date,i.amount::numeric(18,2) receivable_amount,coalesce(p.paid_amount,0)::numeric(18,2) received_amount,greatest(i.amount-coalesce(p.paid_amount,0),0)::numeric(18,2) outstanding_amount,p.last_received_on,case when coalesce(p.paid_amount,0)>=i.amount then 'paid' when coalesce(p.paid_amount,0)>0 and i.due_date<current_date then 'partial_overdue' when coalesce(p.paid_amount,0)>0 then 'partial' when i.due_date<current_date then 'overdue' else 'pending' end status,case when coalesce(p.paid_amount,0)<i.amount and i.due_date<current_date then current_date-i.due_date else 0 end days_overdue,case when coalesce(p.paid_amount,0)>=i.amount then 'paid' when i.due_date>=current_date then 'current' when current_date-i.due_date between 1 and 7 then '01_07' when current_date-i.due_date between 8 and 15 then '08_15' when current_date-i.due_date between 16 and 30 then '16_30' when current_date-i.due_date between 31 and 60 then '31_60' when current_date-i.due_date between 61 and 90 then '61_90' else '90_plus' end aging_bucket
from public.measurement_finance_links l join public.measurements m on m.tenant_id=l.tenant_id and m.company_id=l.company_id and m.id=l.measurement_id join public.engineering_contracts c on c.tenant_id=m.tenant_id and c.company_id=m.company_id and c.id=m.contract_id join public.works w on w.tenant_id=c.tenant_id and w.company_id=c.company_id and w.id=c.work_id join public.financial_installments i on i.tenant_id=l.tenant_id and i.company_id=l.company_id and i.id=l.financial_installment_id left join paid p on p.tenant_id=i.tenant_id and p.company_id=i.company_id and p.installment_id=i.id;
create view public.engineering_receivables_risk_dashboard with(security_invoker=true) as select tenant_id,company_id,work_id,work_name,count(*) receivable_count,sum(receivable_amount)::numeric(18,2) receivable_total,sum(received_amount)::numeric(18,2) received_total,sum(outstanding_amount)::numeric(18,2) outstanding_total,sum(case when status in('overdue','partial_overdue') then outstanding_amount else 0 end)::numeric(18,2) overdue_total,count(*) filter(where status in('overdue','partial_overdue')) overdue_count,max(days_overdue) max_days_overdue,case when sum(outstanding_amount)>0 then round(sum(case when status in('overdue','partial_overdue') then outstanding_amount else 0 end)*100/sum(outstanding_amount),2) else 0 end overdue_percent from public.engineering_receivables_aging group by tenant_id,company_id,work_id,work_name;
commit;